-- BIOLOGY primary: three concepts where neither Psychology nor Sociology is
-- intrinsic. Foraging is behavioural ecology stated for any animal; mating
-- systems and inclusive fitness are evolutionary mechanisms. They keep the
-- PSYCH_SOC section because the MCAT examines them there.
SELECT id, 'BIOLOGY', 'PRIMARY' FROM public.concepts
WHERE slug IN ('FORAGING_AND_ANIMAL_BEHAVIOR', 'INCLUSIVE_FITNESS_AND_EVOLUTIONARY_GAME_THEORY', 'MATING_SYSTEMS_AND_SEXUAL_SELECTION');

