-- ────────────────────────────────────────────────────────────
-- 4. Widening the eight reused Biology objects
--
-- Each gains PSYCH_SOC as a SECONDARY section: their Psych/Soc cards are the
-- evidence they are examined there. Six also gain PSYCHOLOGY as a SECONDARY
-- discipline. Natural Selection & Fitness and Neurulation & Neural Crest do
-- NOT: evolution and embryology stay Biology, and a psychology label would be a
-- claim the cards do not support.
--
-- Principles of Biomedical Ethics is deliberately absent. It already claims
-- PSYCH_SOC, and its discipline stays UNRESOLVED because normative medical
-- ethics is neither psychology nor sociology.
-- ────────────────────────────────────────────────────────────
SELECT id, 'PSYCH_SOC', FALSE FROM public.concepts WHERE canonical_name IN ('Cutaneous Mechanoreceptors', 'Hypothalamus & Pituitary', 'Neuron Functional Types', 'Gonads, Pineal & Other Tissues', 'Reflex Arcs', 'Adrenal Glands', 'Natural Selection & Fitness', 'Neurulation & Neural Crest')
ON CONFLICT DO NOTHING;

SELECT id, 'PSYCHOLOGY', 'SECONDARY' FROM public.concepts WHERE canonical_name IN ('Cutaneous Mechanoreceptors', 'Hypothalamus & Pituitary', 'Neuron Functional Types', 'Gonads, Pineal & Other Tissues', 'Reflex Arcs', 'Adrenal Glands')
ON CONFLICT DO NOTHING;

SELECT id, 'Sensing the environment', FALSE FROM public.concepts WHERE canonical_name = 'Cutaneous Mechanoreceptors' ON CONFLICT DO NOTHING;
SELECT id, 'Responding to the world', FALSE FROM public.concepts WHERE canonical_name = 'Hypothalamus & Pituitary' ON CONFLICT DO NOTHING;
SELECT id, 'Responding to the world', FALSE FROM public.concepts WHERE canonical_name = 'Neuron Functional Types' ON CONFLICT DO NOTHING;
SELECT id, 'Responding to the world', FALSE FROM public.concepts WHERE canonical_name = 'Gonads, Pineal & Other Tissues' ON CONFLICT DO NOTHING;
SELECT id, 'Responding to the world', FALSE FROM public.concepts WHERE canonical_name = 'Reflex Arcs' ON CONFLICT DO NOTHING;
SELECT id, 'Responding to the world', FALSE FROM public.concepts WHERE canonical_name = 'Adrenal Glands' ON CONFLICT DO NOTHING;
SELECT id, 'Individual influences on behavior', FALSE FROM public.concepts WHERE canonical_name = 'Natural Selection & Fitness' ON CONFLICT DO NOTHING;
SELECT id, 'Responding to the world', FALSE FROM public.concepts WHERE canonical_name = 'Neurulation & Neural Crest' ON CONFLICT DO NOTHING;

-- ────────────────────────────────────────────────────────────
-- 5. The 778 card mappings, one PRIMARY each
-- ────────────────────────────────────────────────────────────

-- ────────────────────────────────────────────────────────────
-- 6. Verification inside the transaction. Anything unexpected is a reason to
--    ROLLBACK rather than COMMIT.
-- ────────────────────────────────────────────────────────────
SELECT
  (SELECT count(*) FROM public.concepts)                                  AS objects,       -- 1085
  (SELECT count(*) FROM public.concepts WHERE object_type='CONTENT')      AS content,       -- 1053
  (SELECT count(*) FROM public.concepts WHERE object_type='REASONING')    AS reasoning,     -- 12
  (SELECT count(*) FROM public.concepts WHERE object_type='QUANTITATIVE') AS quantitative,  -- 20
  (SELECT count(*) FROM public.flashcard_concepts)                        AS card_mappings, -- 1961
  (SELECT count(*) FROM public.question_concepts)                         AS q_mappings;    -- 2659 unchanged

-- Every psych_soc card mapped exactly once. Expect 778 and 0.
SELECT count(*) AS psych_soc_cards, count(*) FILTER (WHERE n <> 1) AS not_exactly_one
FROM (SELECT f.id, count(fc.concept_id) AS n
      FROM public.flashcards f
      JOIN public.flashcard_decks d ON d.id=f.deck_id AND d.section='psych_soc'
      LEFT JOIN public.flashcard_concepts fc ON fc.flashcard_id=f.id
      GROUP BY f.id) t;

-- Discipline distribution among the 239 newly seeded concepts. Expect
-- PSYCHOLOGY 178 primary + 3 secondary, SOCIOLOGY 58 primary + 7 secondary,
-- BIOLOGY 3 primary + 59 secondary.
SELECT cd.discipline_code, cd.role, count(*)
FROM public.concept_disciplines cd
JOIN public.concepts c ON c.id=cd.concept_id
JOIN public.concept_sections cs ON cs.concept_id=c.id AND cs.section_code='PSYCH_SOC' AND cs.is_primary
GROUP BY 1,2 ORDER BY 1,2;

-- All twelve categories present and non-empty. Expect 12 rows.
SELECT content_category, count(*) FROM public.concept_content_categories
WHERE content_category IN ('Sensing the environment', 'Making sense of the environment', 'Responding to the world', 'Individual influences on behavior', 'Social processes that influence human behavior', 'Attitude and behavior change', 'Self-identity', 'Social thinking', 'Social interactions', 'Understanding social structure', 'Demographic characteristics and processes', 'Social inequality')
GROUP BY 1 ORDER BY 2 DESC;

-- Every new Psych/Soc concept carries a category. Expect zero rows.
SELECT 'psych_soc concept without a category' AS problem, c.slug FROM public.concepts c
JOIN public.concept_sections cs ON cs.concept_id=c.id AND cs.section_code='PSYCH_SOC' AND cs.is_primary
WHERE NOT EXISTS (SELECT 1 FROM public.concept_content_categories k WHERE k.concept_id=c.id);

-- No cross-cutting object acquired taxonomy, and no non-CONTENT reached
-- question_concepts. Expect zero and zero.
SELECT (SELECT count(*) FROM public.concept_sections s JOIN public.concepts c ON c.id=s.concept_id
          WHERE c.object_type<>'CONTENT') AS noncontent_taxonomy,
       (SELECT count(*) FROM public.question_concepts qc JOIN public.concepts c ON c.id=qc.concept_id
          WHERE c.object_type<>'CONTENT') AS noncontent_questions;

-- Nothing unresolved, no provenance overstated. Expect 0 and 0.
SELECT (SELECT count(*) FROM public.flashcard_concepts WHERE concept_id IS NULL) AS unresolved,
       (SELECT count(*) FROM public.flashcard_concepts
         WHERE mapping_status='HUMAN_VALIDATED' OR source IN ('DETERMINISTIC','DETERMINISTIC_EXACT','LEGACY_EXACT')) AS overstated;

COMMIT;

